"""Original mood-disorder questions: diagnosis and clinically important distinctions."""
from qbank_authoring import question,ref
rows=[]
DE=ref('NICE depression in adults: assessment and management','https://www.nice.org.uk/guidance/ng222/chapter/Recommendations')
BP=ref('Indian Psychiatric Society bipolar disorder guideline: 2025 update','https://pmc.ncbi.nlm.nih.gov/articles/PMC12900052/')
CA=ref('CANMAT/ISBD bipolar disorder evidence update','https://pmc.ncbi.nlm.nih.gov/articles/PMC11058959/')
NI=ref('NIMH bipolar disorder','https://www.nimh.nih.gov/health/publications/bipolar-disorder')
def q(stem,answer,others,title,principle,details,application,clinical,table,refs,style='direct'):
    rows.append(question(stem,answer,others,title,principle,details,application,clinical,table,refs,style))

q('An adult has 3 weeks of depressed mood, anhedonia, insomnia, low energy, guilt and impaired concentration with major functional decline. No mania, substance cause or medical explanation is found. Which diagnosis best fits?', 'A major depressive episode',[
 ('Persistent depressive disorder established by this duration','A chronic depressive disorder requires a substantially longer course.'),('Adjustment disorder solely because there was a recent stressor','A stressor does not override a full depressive episode.'),('Bipolar II disorder without any hypomanic history','Bipolar II requires a qualifying hypomanic episode as well as depression.')],
 'Diagnose a syndrome, then establish its longitudinal context','**Sustained mood/anhedonia symptoms with associated changes and impairment support a depressive episode.**',['Assess symptom duration, severity and safety.','A depressive episode can occur in unipolar or bipolar illness.'],'**Ask specifically about prior elevated or irritable high-energy periods.**',['Review medical, medication and substance contributors.','Use functional history and collateral information rather than a screening score alone.'],[['Current syndrome','Major depressive episode'],['Longitudinal diagnosis','Requires past-episode assessment'],['Stressor','Does not exclude depression']],[DE,CA],style='clinical_scenario')

q('Which feature most strongly distinguishes hypomania from mania?', 'Hypomania lacks marked functional impairment, hospitalization necessity or psychosis attributable to the episode',[
 ('Hypomania has no increase in energy','Increased energy/activity is part of the syndrome.'),('Hypomania always lasts longer than mania','Duration alone does not define relative severity in that way.'),('Any elevated mood with psychosis is still hypomania if brief','Psychosis indicates manic-level severity rather than hypomania.')],
 'Severity and consequences matter as well as duration','**Hypomania represents a clear change from baseline without the severe consequences defining mania.**',['Reduced need for sleep is different from insomnia with fatigue.','Collateral history often identifies changes the patient views as productive.'],'**Assess risk taking, judgment and the full time course.**',['A hospitalized or psychotic presentation may meet mania criteria despite shorter duration.','Exclude substance and medical causes.'],[['Hypomania','Observable change without marked impairment/psychosis'],['Mania','Marked impairment, hospitalization or psychosis'],['History','Energy, sleep and consequences']],[NI,BP])

q('A patient has a past major depressive episode and a 5-day period of increased energy, little need for sleep, talkativeness and unusual spending, without psychosis or marked impairment. There has never been mania. Which diagnosis is most likely?', 'Bipolar II disorder',[
 ('Bipolar I disorder','This requires a manic episode, which is not described.'),('Cyclothymic disorder','The history contains a full major depressive episode and a qualifying hypomanic syndrome.'),('Recurrent unipolar depression','The hypomanic history changes the longitudinal diagnosis.')],
 'The polarity history changes treatment planning','**Bipolar II combines major depression with hypomania and no manic episode.**',['The depressive burden may be substantial despite the less severe elevated phase.','Do not infer a mild overall illness from the term hypomania.'],'**Use a bipolar-informed treatment plan.**',['Assess family history, episode recurrence and antidepressant switches.','Review the history with collateral information when possible.'],[['Depression','Present'],['Hypomania','Present'],['Mania','Absent']],[NI,CA],style='clinical_scenario')

q('A patient has a fully syndromal manic episode with no prior major depression. Which diagnosis can be established after excluding secondary causes?', 'Bipolar I disorder',[
 ('Bipolar II disorder','Bipolar II excludes a history of mania.'),('Major depressive disorder','There is no current requirement for depression and mania changes the diagnosis.'),('Cyclothymic disorder','Full mania is outside the subthreshold cycling definition.')],
 'Depression is not required to diagnose bipolar I','**One qualifying manic episode can establish the disorder.**',['Establish that the syndrome is not better explained by substances, medication or medical illness.','A first late-life manic presentation warrants particular secondary-cause assessment.'],'**Treat acute risk and plan maintenance care.**',['Assess sleep, behavior, psychosis and decision-making capacity.','Obtain collateral history and evaluate functional consequences.'],[['Required polarity','Mania'],['Prior depression','Not mandatory'],['Secondary causes','Must be assessed']],[NI,BP],style='clinical_scenario')

q('Which symptom is more specific for a manic syndrome than ordinary anxiety-related insomnia?', 'Feeling rested after very little sleep while remaining unusually energetic',[
 ('Wanting sleep but being unable to sleep and feeling exhausted','This is insomnia rather than decreased need for sleep.'),('Worry-related difficulty falling asleep with daytime fatigue','This can occur in anxiety and depression.'),('Early awakening with low mood and low energy','This is more compatible with a depressive sleep pattern.')],
 'Ask about the need for sleep, not only hours slept','**Mania can reduce the subjective need for sleep.**',['The finding becomes meaningful with increased activity, mood change and other symptoms.','A single sleepless night does not establish bipolar disorder.'],'**Clarify the episodic change from baseline.**',['Review stimulants, shift work and other explanations.','Use collateral observations of energy and behavior.'],[['Insomnia','Unable to sleep despite need'],['Manic sleep change','Little sleep without usual fatigue'],['Diagnosis','Requires the broader syndrome']],[BP,CA])

q('A person has recurrent depression beginning in youth, a first-degree relative with bipolar disorder and antidepressant-associated sustained elevated energy. What is the most important next diagnostic step?', 'Assess carefully for bipolar-spectrum episodes and the nature of the antidepressant-associated switch',[
 ('Automatically increase antidepressant monotherapy without a polarity review','This may worsen an unrecognized bipolar illness.'),('Diagnose bipolar I solely from family history','Risk factors are not a substitute for a qualifying episode.'),('Exclude bipolar illness because all presentations involved low mood','Past elevated periods may not have prompted help-seeking.')],
 'Clues should prompt a better history rather than an automatic label','**Early onset, familial loading and treatment-emergent activation raise suspicion.**',['Distinguish transient jitteriness from a full sustained mood episode.','Assess energy, sleep, duration and consequences.'],'**Use a longitudinal specialist-informed formulation.**',['Obtain collateral information where possible.','Consider medical and substance-related explanations for activation.'],[['Risk clues','Early onset/family history/switch'],['Required step','Episode characterization'],['Avoid','Premature label or blind escalation']],[CA],style='clinical_scenario')

q('What does rapid cycling in bipolar disorder conventionally mean?', 'At least four qualifying mood episodes within 12 months',[
 ('Mood changes several times during one afternoon','Brief affective shifts are not equivalent to distinct qualifying episodes.'),('Two depressive episodes over an entire lifetime','This does not meet the frequency definition.'),('Any episode that responds to medication within a week','The term describes illness course rather than treatment speed.')],
 'Episodes require syndromal and temporal definition','**Rapid cycling is a course specifier, not a synonym for moment-to-moment lability.**',['Episodes are separated or change polarity according to diagnostic criteria.','Evaluate thyroid dysfunction, substances and medication-related destabilization.'],'**Review longitudinal treatment and adherence.**',['Antidepressants can be problematic in selected rapid-cycling cases.','Use a chart of episodes and intervening periods.'],[['Frequency','Four or more/year'],['Unit','Qualifying episode'],['Assessment','Triggers and longitudinal course']],[NI,CA])

q('An adult has years of fluctuating subthreshold depressive and hypomanic symptoms without a full depressive, manic or hypomanic episode during the defining initial period. Which diagnosis is most consistent?', 'Cyclothymic disorder',[
 ('Bipolar I disorder','A full manic episode is not described.'),('Bipolar II disorder','That requires full hypomania and major depression.'),('Recurrent major depressive disorder','The described depressive periods do not meet full episode criteria.')],
 'Subthreshold cycling differs from full episodes','**Cyclothymia requires a persistent fluctuating course meeting its duration and exclusion criteria.**',['Brief ordinary mood variation is not sufficient.','Substances, personality patterns and other disorders can mimic lability.'],'**Assess chronicity, symptom-free intervals and impairment.**',['Use a longitudinal history rather than one visit.','Reassess if full episodes later develop.'],[['Cyclothymia','Chronic subthreshold polarity shifts'],['Bipolar II','Full hypomania plus major depression'],['Bipolar I','Full mania']],[BP,CA])

q('A depressed patient has fixed beliefs of deserved punishment and financial ruin despite evidence to the contrary. The psychosis occurs only during severe depressive episodes. Which formulation is most appropriate?', 'Major depression with psychotic features',[
 ('Schizoaffective disorder established by any psychotic symptom','That requires the relevant longitudinal relationship including psychosis outside mood episodes.'),('Delusional disorder as the best explanation for the entire syndrome','The delusions occur within a severe full depressive syndrome.'),('Bipolar I disorder solely because psychosis is present','Psychosis in depression does not establish mania.')],
 'The timing of psychosis relative to mood episodes is diagnostic','**Psychotic symptoms can occur within a severe depressive episode.**',['Mood congruence can support characterization but is not the only requirement.','Assess intake, function, self-neglect and safety urgently.'],'**Arrange specialist treatment for both mood and psychosis.**',['Combination pharmacotherapy or ECT may be appropriate.','Revisit the longitudinal diagnosis if psychosis occurs outside mood episodes.'],[['Psychotic depression','Psychosis during depressive episode'],['Bipolar diagnosis','Requires polarity history'],['Schizoaffective','Different longitudinal criteria']],[DE],style='clinical_scenario')

q('An older adult has low mood, slowed thinking and memory complaints. Which approach best distinguishes depression-related cognitive impairment from a neurocognitive disorder?', 'Assess mood, cognition and function longitudinally, including collateral history and response to treatment',[
 ('Use the complaint of forgetfulness alone to diagnose dementia','Subjective complaints are not specific.'),('Assume depression excludes coexisting neurodegeneration','The two can coexist.'),('Treat one normal brief cognitive score as permanent exclusion of cognitive disease','Brief tests and early disease have limitations.')],
 'Mood and cognition interact without being mutually exclusive','**Depression can impair attention, processing and memory performance.**',['Functional decline, progression and collateral observations are important.','Evaluate medications, sensory impairment and reversible medical contributors.'],'**Treat the mood disorder and reassess cognition over time.**',['Refer when progressive or disproportionate deficits persist.','Avoid using a simplistic pseudodementia label as a final diagnosis.'],[['Depression','Can impair cognition'],['Neurodegeneration','Can coexist'],['Best assessment','Longitudinal and collateral']],[DE],style='clinical_scenario')

q('A bereaved patient has pervasive anhedonia, severe worthlessness, marked impairment and sustained depressive symptoms meeting a full episode. Which statement is correct?', 'Bereavement does not automatically exclude a major depressive episode',[
 ('Any depression after a death is normal grief by definition','A full syndrome can require treatment despite an understandable trigger.'),('A recent death proves bipolar depression','The trigger does not establish bipolar polarity.'),('Any sadness during grief requires an antidepressant','Treatment depends on the syndrome, severity, preference and risk, not sadness alone.')],
 'Context informs diagnosis without erasing severe illness','**Grief and depression can overlap or coexist.**',['Assess the quality, persistence and functional consequences of symptoms.','Cultural context and the person’s experience matter.'],'**Offer proportionate support and syndrome-directed treatment.**',['Evaluate safety and self-care.','Do not pathologize ordinary grief or dismiss a severe depressive episode.'],[['Grief','Contextual response with variable course'],['Depressive episode','Syndromal assessment'],['Treatment','Severity and individual needs']],[DE],style='clinical_scenario')

q('A patient develops first-onset manic symptoms at age 68 while taking high-dose corticosteroids. Which assessment is essential?', 'Evaluate medication-induced and medical causes before assigning a primary lifelong bipolar diagnosis',[
 ('Diagnose primary bipolar I from age and mood alone','The temporal medication relationship and late onset require assessment.'),('Exclude mania because the patient is older','Manic syndromes can occur in older adults.'),('Assume a steroid-related episode cannot require urgent psychiatric treatment','Severity and risk still require treatment even when secondary.')],
 'A syndrome and its cause are separate clinical questions','**Corticosteroids, neurological illness, endocrine disease and substances can produce manic presentations.**',['Assess the timing and dose relationship.','Review delirium features and neurological/systemic findings.'],'**Coordinate medical and psychiatric care.**',['Adjust the precipitating treatment when clinically feasible and safe.','Treat agitation, sleep loss, psychosis and dangerous behavior as indicated.'],[['Late onset','Secondary-cause review'],['Drug timing','Important clue'],['Treatment','Cause plus acute syndrome']],[BP,CA],style='clinical_scenario')
